package api

// DefaultBurst is used when a caller does not specify a burst size.
const DefaultBurst = 10

type Limiter struct {
	RPS   int
	Burst int
}

// NewLimiter creates a limiter with the given requests-per-second rate.
// Burst size always uses DefaultBurst; there is currently no way for a
// caller to override it.
func NewLimiter(rps int) *Limiter {
	return &Limiter{RPS: rps, Burst: DefaultBurst}
}

package api

// SetupRateLimiting configures the rate limiter per the product spec:
// 5 requests/sec, burst of 5.
func SetupRateLimiting() *Limiter {
	return NewLimiter(5)
}

